{
  "name": "@nofendian17/opencode-relay-plugin",
  "version": "2.0.8",
  "description": "Route OpenCode v2 opencode.ai traffic through relay endpoint(s) with round-robin, failover, and direct fallback. Other providers are left untouched.",
  "type": "module",
  "main": "./index.ts",
  "exports": {
    ".": "./index.ts"
  },
  "files": [
    "index.ts",
    "README.md"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "relay",
    "proxy"
  ],
  "license": "MIT",
  "scripts": {
    "test": "node --test test/relay.test.ts",
    "typecheck": "tsc --noEmit"
  },
  "peerDependencies": {
    "@opencode/plugin": "^2"
  },
  "devDependencies": {
    "@opencode/plugin": "^2.0.28",
    "@types/node": "^26.6.5",
    "typescript": "^5.9.3"
  }
}
